class Medication{const Medication({required this.id,required this.name,this.dosage,this.instructions,required this.isActive,required this.schedules});factory Medication.fromJson(Map<String,dynamic> j)=>Medication(id:j['id'] as String,name:j['name'] as String,dosage:j['dosage'] as String?,instructions:j['instructions'] as String?,isActive:j['isActive'] as bool,schedules:(j['schedules'] as List<dynamic>).map((e)=>MedicationSchedule.fromJson(e)).toList());final String id,name;final String? dosage,instructions;final bool isActive;final List<MedicationSchedule> schedules;}
class MedicationSchedule{const MedicationSchedule({required this.id,required this.time,required this.frequency,required this.startDate,this.endDate,required this.isActive});factory MedicationSchedule.fromJson(Map<String,dynamic> j)=>MedicationSchedule(id:j['id'] as String,time:j['time'] as String,frequency:j['frequency'] as String,startDate:j['startDate'] as String,endDate:j['endDate'] as String?,isActive:j['isActive'] as bool);final String id,time,frequency,startDate;final String? endDate;final bool isActive;}
class MedicationAdherence{const MedicationAdherence({required this.days,required this.total,required this.taken,required this.percentage});factory MedicationAdherence.fromJson(Map<String,dynamic> j)=>MedicationAdherence(days:j['days'] as int,total:j['totalDosesLogged'] as int,taken:j['takenDoses'] as int,percentage:(j['adherencePercentage'] as num).toDouble());final int days,total,taken;final double percentage;}